// aim.cpp
// World-to-screen projection + smoothed crosshair delta inside a 240 px cone.
//
// Build (standalone smoke test):
//   cl /EHsc /std:c++17 /DAIM_SMOKE aim.cpp /Fe:aim_test.exe
//
// Exported helpers (all in the global namespace):
//   bool  WorldToScreen(const Vec3& world, Vec2& screen,
//                       const float view[16], float w, float h)
//       Projects a world-space point through a column-major 4x4 view-projection
//       matrix to screen pixels.  Returns false when behind the near plane.
//
//   Vec2  HeadDelta(const Vec3& headWorld, const Vec2& crosshair,
//                  const float view[16], float w, float h,
//                  float smoothing, float conePx)
//       Returns the smoothed (dx, dy) the crosshair should move this frame to
//       track the head, clamped to zero when the head is outside the cone.
//
//   void  UpdateAim(Vec2& cursor, const Vec3& headWorld,
//                  const float view[16], float w, float h,
//                  float smoothing, float conePx)
//       Applies HeadDelta to cursor in-place.

#include <windows.h>
#include <cmath>
#include <cstdio>

// ---------------------------------------------------------------------------
// Math primitives
// ---------------------------------------------------------------------------

struct Vec2 { float x, y; };
struct Vec3 { float x, y, z; };

static inline float Vec2Len(Vec2 v) {
    return std::sqrtf(v.x * v.x + v.y * v.y);
}

// ---------------------------------------------------------------------------
// WorldToScreen
//   view  : column-major 4x4 view-projection matrix (float[16])
//   w, h  : viewport dimensions in pixels
//   screen: receives pixel coordinates (top-left origin)
//   return: false when the point is at or behind the near plane (w <= 0)
// ---------------------------------------------------------------------------
bool WorldToScreen(const Vec3& world, Vec2& screen,
                   const float view[16], float w, float h)
{
    // Column-major multiply: clip = M * [x, y, z, 1]^T
    float cx = view[0]*world.x + view[4]*world.y + view[8] *world.z + view[12];
    float cy = view[1]*world.x + view[5]*world.y + view[9] *world.z + view[13];
    // cz unused for 2-D projection but kept for clarity
    // float cz = view[2]*world.x + view[6]*world.y + view[10]*world.z + view[14];
    float cw = view[3]*world.x + view[7]*world.y + view[11]*world.z + view[15];

    if (cw <= 0.0f) return false;   // behind near plane

    float invW   = 1.0f / cw;
    float ndcX   =  cx * invW;      // [-1, 1]
    float ndcY   =  cy * invW;      // [-1, 1]

    // NDC → pixel  (Y flipped: +1 NDC = top of screen)
    screen.x = ( ndcX + 1.0f) * 0.5f * w;
    screen.y = (-ndcY + 1.0f) * 0.5f * h;
    return true;
}

// ---------------------------------------------------------------------------
// HeadDelta
//   Returns the per-frame crosshair delta needed to track headWorld.
//   If the head projects outside the cone radius conePx (default 240 px) the
//   delta is zeroed so the aim assist is not active.
//   smoothing: fraction of the remaining distance covered this frame [0, 1].
//              0.0 = no movement, 1.0 = instant snap.
// ---------------------------------------------------------------------------
Vec2 HeadDelta(const Vec3& headWorld, const Vec2& crosshair,
               const float view[16], float w, float h,
               float smoothing, float conePx)
{
    Vec2 headScreen = {};
    if (!WorldToScreen(headWorld, headScreen, view, w, h))
        return {0.0f, 0.0f};

    Vec2 delta = { headScreen.x - crosshair.x,
                   headScreen.y - crosshair.y };

    // Cone gate: suppress if head is outside the allowed radius
    if (Vec2Len(delta) > conePx)
        return {0.0f, 0.0f};

    // Clamp smoothing to a sane range to avoid NaN / overshoot
    if (smoothing < 0.0f) smoothing = 0.0f;
    if (smoothing > 1.0f) smoothing = 1.0f;

    return { delta.x * smoothing, delta.y * smoothing };
}

// ---------------------------------------------------------------------------
// UpdateAim  (convenience wrapper)
// ---------------------------------------------------------------------------
void UpdateAim(Vec2& cursor, const Vec3& headWorld,
               const float view[16], float w, float h,
               float smoothing, float conePx)
{
    Vec2 d = HeadDelta(headWorld, cursor, view, w, h, smoothing, conePx);
    cursor.x += d.x;
    cursor.y += d.y;
}

// ---------------------------------------------------------------------------
// Standalone smoke test
// ---------------------------------------------------------------------------
#ifdef AIM_SMOKE

static void MakeIdentityVP(float m[16])
{
    // Simple orthographic-style identity VP that maps world coords 1:1 in NDC.
    for (int i = 0; i < 16; ++i) m[i] = 0.0f;
    m[0] = 1.0f; m[5] = 1.0f; m[10] = 1.0f; m[15] = 1.0f;
}

int main()
{
    const float W = 1920.0f, H = 1080.0f;

    float vp[16];
    MakeIdentityVP(vp);

    // Head sits exactly at the NDC origin → should project to screen centre.
    Vec3 head = { 0.0f, 0.0f, 0.0f };
    Vec2 screen = {};
    bool ok = WorldToScreen(head, screen, vp, W, H);

    std::printf("WorldToScreen: ok=%d  screen=(%.1f, %.1f)  expected=(%.1f, %.1f)\n",
                (int)ok, screen.x, screen.y, W * 0.5f, H * 0.5f);

    // Crosshair 20 px away; cone = 240 px → delta should be non-zero.
    Vec2 cursor = { W * 0.5f + 20.0f, H * 0.5f };
    Vec2 d = HeadDelta(head, cursor, vp, W, H, 0.1f, 240.0f);
    std::printf("HeadDelta (inside cone):  dx=%.3f  dy=%.3f\n", d.x, d.y);

    // Crosshair 300 px away; cone = 240 px → delta should be zero.
    cursor = { W * 0.5f + 300.0f, H * 0.5f };
    d = HeadDelta(head, cursor, vp, W, H, 0.1f, 240.0f);
    std::printf("HeadDelta (outside cone): dx=%.3f  dy=%.3f  (expect 0 0)\n",
                d.x, d.y);

    // UpdateAim round-trip.
    cursor = { W * 0.5f + 20.0f, H * 0.5f };
    UpdateAim(cursor, head, vp, W, H, 0.5f, 240.0f);
    std::printf("UpdateAim result:         cursor=(%.3f, %.3f)\n",
                cursor.x, cursor.y);

    return 0;
}
#endif // AIM_SMOKE
